function delayedValue() {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(42);
    }, 100);
  });
}

function totalAfterDelay(prices, ms) {
  return new Promise((resolve) => {
    setTimeout(() => {
      let total = 0;

      for (const price of prices) {
        total += Number(price);
      }

      resolve(total);
    }, ms);
  });
}
